export default class GeneralSearchIndex {
  currentId = '';
  data = {};
  groups = {};
  group(id, data) {
    this.groups[id] = data;
    return this;
  }
  for(id) {
    this.currentId = id;
    return this;
  }
  add(type, items) {
    this.data[this.currentId] ||= {
      settings: [],
      permissions: []
    };
    this.data[this.currentId][type].push(...items);
  }
  getData() {
    return this.data;
  }
  getGroup(id) {
    return this.groups[id] || null;
  }
}
flarum.reg.add('core', 'admin/states/GeneralSearchIndex', GeneralSearchIndex);